def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    import re

    token_re = re.compile(r"[0-9]+|[A-Z]+[0-9]*|<>|<=|>=|[-+*/(),:=<>]")
    functions = {"SUM", "MIN", "MAX", "IF"}
    precedence = {
        "=": 0, "<>": 0, "<": 0, "<=": 0, ">": 0, ">=": 0,
        "+": 1, "-": 1,
        "*": 2, "/": 2,
        "neg": 3,
        ":": 4,
    }

    def integer(text):
        text = text.strip()
        negative = text.startswith("-")
        if text[:1] in ("-", "+"):
            text = text[1:]
        value = 0
        for i in range(0, len(text), 9):
            part = text[i:i + 9]
            value = value * (10 ** len(part)) + int(part)
        return -value if negative else value

    def parse(formula):
        values = []
        operators = []
        pending_function = None
        expect_operand = True

        def reduce_operator():
            op = operators.pop()
            if op == "neg":
                values.append(("neg", values.pop()))
            else:
                right = values.pop()
                left = values.pop()
                values.append(("binary", op, left, right))

        for match in token_re.finditer(formula):
            token = match.group()

            if token[0].isdigit():
                values.append(("number", integer(token)))
                expect_operand = False

            elif token in functions:
                pending_function = token

            elif token[0].isalpha():
                values.append(("reference", token))
                expect_operand = False

            elif token == "(":
                operators.append(("(", pending_function, len(values)))
                pending_function = None
                expect_operand = True

            elif token == ",":
                while isinstance(operators[-1], str):
                    reduce_operator()
                expect_operand = True

            elif token == ")":
                while isinstance(operators[-1], str):
                    reduce_operator()
                _, function, start = operators.pop()
                if function is not None:
                    arguments = values[start:]
                    del values[start:]
                    values.append(("call", function, arguments))
                expect_operand = False

            else:
                op = "neg" if token == "-" and expect_operand else token
                while operators and isinstance(operators[-1], str):
                    previous = operators[-1]
                    if precedence[previous] < precedence[op]:
                        break
                    if previous == op == "neg":
                        break
                    reduce_operator()
                operators.append(op)
                expect_operand = True

        while operators:
            reduce_operator()
        return values[0]

    def expand_arguments(arguments):
        for argument in arguments:
            if argument[0] == "binary" and argument[1] == ":":
                first = argument[2][1]
                second = argument[3][1]
                col1, col2 = sorted((ord(first[0]), ord(second[0])))
                row1, row2 = sorted((int(first[1:]), int(second[1:])))
                for row in range(row1, row2 + 1):
                    for col in range(col1, col2 + 1):
                        name = chr(col) + str(row)
                        if name in cells:
                            yield ("reference", name)
            else:
                yield argument

    def binary(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if op == "/":
            if right == 0:
                return "#DIV/0!"
            quotient = abs(left) // abs(right)
            return -quotient if (left < 0) != (right < 0) else quotient
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        return left >= right

    cache = {}
    active = set()

    for root in cells:
        if root in cache:
            continue

        tasks = [("cell", root)]
        result = 0

        while tasks:
            task = tasks.pop()
            kind = task[0]

            if kind == "cell":
                name = task[1]
                if name in cache:
                    result = cache[name]
                elif name not in cells:
                    result = 0
                elif name in active:
                    result = "#CYCLE!"
                else:
                    content = cells[name].strip()
                    if not content.startswith("="):
                        result = integer(content)
                        cache[name] = result
                    else:
                        active.add(name)
                        tasks.append(("finish", name))
                        tasks.append(("eval", parse(content[1:])))

            elif kind == "finish":
                name = task[1]
                cache[name] = result
                active.remove(name)

            elif kind == "eval":
                node = task[1]
                node_kind = node[0]

                if node_kind == "number":
                    result = node[1]

                elif node_kind == "reference":
                    tasks.append(("cell", node[1]))

                elif node_kind == "neg":
                    tasks.append(("negate",))
                    tasks.append(("eval", node[1]))

                elif node_kind == "binary":
                    tasks.append(("left", node[1], node[3]))
                    tasks.append(("eval", node[2]))

                else:
                    function, arguments = node[1], node[2]
                    if function == "IF":
                        tasks.append(("choose", arguments[1], arguments[2]))
                        tasks.append(("eval", arguments[0]))
                    else:
                        tasks.append((
                            "aggregate_next",
                            function,
                            expand_arguments(arguments),
                            None,
                        ))

            elif kind == "negate":
                if not isinstance(result, str):
                    result = -result

            elif kind == "left":
                if not isinstance(result, str):
                    tasks.append(("right", task[1], result))
                    tasks.append(("eval", task[2]))

            elif kind == "right":
                if not isinstance(result, str):
                    result = binary(task[1], task[2], result)

            elif kind == "choose":
                if not isinstance(result, str):
                    tasks.append(("eval", task[1] if result else task[2]))

            elif kind == "aggregate_next":
                function, arguments, accumulated = task[1:]
                argument = next(arguments, None)
                if argument is None:
                    result = 0 if accumulated is None else accumulated
                else:
                    tasks.append((
                        "aggregate_value", function, arguments, accumulated
                    ))
                    tasks.append(("eval", argument))

            elif kind == "aggregate_value":
                if not isinstance(result, str):
                    function, arguments, accumulated = task[1:]
                    if accumulated is None:
                        accumulated = result
                    elif function == "SUM":
                        accumulated += result
                    elif function == "MIN":
                        accumulated = min(accumulated, result)
                    else:
                        accumulated = max(accumulated, result)
                    tasks.append((
                        "aggregate_next", function, arguments, accumulated
                    ))

    return {name: cache[name] for name in cells}
